const sourcePath = 'https://verdantasplanning.com/wp-content/uploads/2026/03/Saybrook-Text-03.26.26-Draft.pdf';
const sourceSlug = 'saybrook-zoning';
const jurisdiction = 'Saybrook Township';
const collection = 'saybrook_zoning_20260326';
const embeddingModel = 'nomic-embed-text';
const ollamaUrl = 'http://ollama:11434/api/embeddings';

function safeText(input) {
  if (!input) return '';
  if (typeof input.text === 'string' && input.text.trim()) return input.text;
  if (typeof input.content === 'string' && input.content.trim()) return input.content;
  if (typeof input.extractedText === 'string' && input.extractedText.trim()) return input.extractedText;
  if (Array.isArray(input.pages)) {
    return input.pages
      .map((page) => (page && typeof page.text === 'string' ? page.text : ''))
      .filter(Boolean)
      .join('\n\n');
  }
  return JSON.stringify(input);
}

function splitIntoChunks(text, maxChars = 1800, overlap = 250) {
  const clean = text.replace(/\r/g, '').replace(/\t/g, ' ').replace(/\u0000/g, '').trim();
  const headingRegex = /(?=^\s*(ARTICLE\s+[A-Z0-9IVXLC]+|SECTION\s+[0-9A-Z.\-]+|Sec\.\s+[0-9A-Z.\-]+|CHAPTER\s+[0-9A-Z.\-]+)\b)/gmi;
  const sections = clean.split(headingRegex).map((part) => part.trim()).filter(Boolean);
  const units = sections.length ? sections : [clean];
  const chunks = [];

  for (const unit of units) {
    if (unit.length <= maxChars) {
      chunks.push(unit);
      continue;
    }

    let start = 0;
    while (start < unit.length) {
      let end = Math.min(unit.length, start + maxChars);
      if (end < unit.length) {
        const nextBreak = Math.max(
          unit.lastIndexOf('\n\n', end),
          unit.lastIndexOf('. ', end),
          unit.lastIndexOf('; ', end)
        );
        if (nextBreak > start + 600) end = nextBreak + 1;
      }
      const chunk = unit.slice(start, end).trim();
      if (chunk) chunks.push(chunk);
      if (end >= unit.length) break;
      start = Math.max(end - overlap, start + 1);
    }
  }

  return chunks;
}

async function embed(text) {
  const requestHelper = this.helpers?.request ?? this.helpers?.httpRequest;
  if (!requestHelper) {
    throw new Error('n8n Code node does not expose an HTTP request helper in this runtime');
  }

  const data = await requestHelper.call(this.helpers, {
    method: 'POST',
    url: ollamaUrl,
    headers: { 'Content-Type': 'application/json' },
    body: {
      model: embeddingModel,
      prompt: text,
    },
    json: true,
  });

  if (!Array.isArray(data.embedding)) {
    throw new Error('Ollama embeddings response did not include an embedding array');
  }
  return data.embedding;
}

const input = $input.first()?.json ?? {};
const text = safeText(input);
if (!text.trim()) {
  throw new Error('No extractable PDF text was found in the upstream node output');
}

const rawChunks = splitIntoChunks(text);
const points = [];
for (let index = 0; index < rawChunks.length; index++) {
  const chunk = rawChunks[index];
  const vector = await embed(chunk);
  points.push({
    id: index + 1,
    vector,
    payload: {
      slug: sourceSlug,
      jurisdiction,
      source_path: sourcePath,
      source_file: 'Saybrook-Text-03.26.26-Draft.pdf',
      document_version: '2026-03-26 draft',
      chunk_index: index + 1,
      point_key: `${sourceSlug}-20260326-${index + 1}`,
      content: chunk,
      char_count: chunk.length
    }
  });
}

return [{
  json: {
    collection,
    point_count: points.length,
    source_slug: sourceSlug,
    source_path: sourcePath,
    points
  }
}];

const qdrant = $input.first()?.json ?? {};
const ingest = $('Chunk + Embed PDF').first().json;
return [{
  json: {
    ok: true,
    collection: ingest.collection,
    point_count: ingest.point_count,
    source_slug: ingest.source_slug,
    source_path: ingest.source_path,
    qdrant_response: qdrant,
    next_step: 'Wire a query path that embeds the user question, searches Qdrant, and synthesizes a cited answer with llama3.'
  }
}];
